css:
@page {
    size: A4;
    margin: 1cm;
}

body {
    font-family: Arial, sans-serif;
    font-size: 11px;
    color: #222;
}

.rental-agreement {
    width: 100%;
}

.agreement-header {
    text-align: center;
    border-bottom: 2px solid #222;
    padding-bottom: 12px;
    margin-bottom: 20px;
}

.agreement-header h1 {
    margin: 0;
    font-size: 24px;
}

.agreement-header h2 {
    margin: 5px 0;
    font-size: 18px;
}

.print-summary {
    font-size: 10px;
    margin-top: 5px;
}

.section {
    margin-bottom: 18px;
}

.section h3 {
    font-size: 14px;
    margin-bottom: 8px;
    border-bottom: 1px solid #999;
    padding-bottom: 4px;
}

.details-table {
    width: 100%;
    border-collapse: collapse;
}

.details-table td {
    padding: 6px;
    border-bottom: 1px solid #ddd;
}

.details-table td:first-child {
    width: 30%;
}


.items-table {
    width: 100%;
    border-collapse: collapse;
}

.items-table th,
.items-table td {
    border: 1px solid #999;
    padding: 7px;
    text-align: left;
}

.items-table th {
    font-weight: bold;
}

.items-table td:nth-child(1),
.items-table td:nth-child(4) {
    text-align: center;
}

.items-table td:nth-child(5),
.items-table td:nth-child(6) {
    text-align: right;
}

.items-table th:nth-child(4),
.items-table th:nth-child(5),
.items-table th:nth-child(6) {
    text-align: right;
}

.total-label {
    text-align: right !important;
    font-weight: bold;
}

.total-value {
    text-align: right !important;
    font-weight: bold;
}


.damage-banner {
    border: 2px solid #000;
    padding: 10px;
    text-align: center;
    font-weight: bold;
    margin: 15px 0;
}

.damage-section {
    text-align: right;
    margin-bottom: 15px;
}


.financial-summary {
    width: 45%;
    margin-left: auto;
    margin-top: 20px;
}

.financial-row {
    display: flex;
    justify-content: space-between;
    padding: 6px 0;
    border-bottom: 1px solid #ddd;
}

.final-amount {
    display: flex;
    justify-content: space-between;
    padding: 12px 0;
    margin-top: 8px;
    border-top: 2px solid #222;
    font-size: 16px;
    font-weight: bold;
}


.signature-section {
    display: flex;
    justify-content: space-between;
    margin-top: 60px;
    page-break-inside: avoid;
}

.signature-box {
    width: 40%;
    text-align: center;
}

.signature-line {
    border-top: 1px solid #222;
    margin-bottom: 8px;
}

.signature-box p {
    margin: 0;
}


.page-break-table {
    page-break-inside: auto;
}

.page-break-table tr {
    page-break-inside: avoid;
    page-break-after: auto;
}


/* Hide interactive elements while printing */
@media print {
    .interactive-elements {
        display: none !important;
    }
}


/* Keep important sections together */
.section {
    page-break-inside: avoid;
}

.financial-summary {
    page-break-inside: avoid;
}
